#![allow(dead_code)]

use std::path::{Path, PathBuf};

pub use styrene_interop_runner::rns_fixtures::RnsFixtureIndex;

pub fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../..")
}

/// Root directory containing JSON fixture files generated by the Python
/// test-vector generator (`tests/interop/python/generate_fixtures.py`).
pub fn fixtures_dir() -> PathBuf {
    repo_root().join("tests").join("interop").join("fixtures")
}

pub fn load_rns_index() -> Result<RnsFixtureIndex, Vec<String>> {
    styrene_interop_runner::rns_fixtures::load_rns_index(&repo_root())
}

pub fn rns_vector<'a>(
    index: &'a RnsFixtureIndex,
    id: &str,
) -> Result<&'a styrene_interop_runner::rns_fixtures::RnsVector, String> {
    styrene_interop_runner::rns_fixtures::rns_vector(index, id)
}

pub fn load_rns_vector_bytes(index: &RnsFixtureIndex, id: &str) -> Result<Vec<u8>, String> {
    styrene_interop_runner::rns_fixtures::load_rns_vector_bytes(index, id)
}

/// Load a JSON fixture file and deserialise it into `T`.
pub fn load_fixture<T: serde::de::DeserializeOwned>(filename: &str) -> T {
    let path = fixtures_dir().join(filename);
    let data = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read fixture {}: {e}", path.display()));
    serde_json::from_str(&data)
        .unwrap_or_else(|e| panic!("failed to parse fixture {}: {e}", path.display()))
}

/// Decode a hex string to bytes.
pub fn hex_decode(s: &str) -> Vec<u8> {
    hex::decode(s).unwrap_or_else(|e| panic!("invalid hex string '{s}': {e}"))
}
